import re

_PATTERN = re.compile(r"(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?")
_SCALES = (86400, 3600, 60, 1)


def parse_duration(s):
    if not isinstance(s, str):
        raise ValueError("expected a string")
    match = _PATTERN.fullmatch(s.strip())
    if match is None:
        raise ValueError("invalid duration: %r" % (s,))
    amounts = match.groups()
    if all(a is None for a in amounts):
        raise ValueError("invalid duration: %r" % (s,))
    return sum(int(a) * scale for a, scale in zip(amounts, _SCALES) if a is not None)
